// Korpus för matchningen (test/match-corpus.test.js): filnamn och mappar som svenska hemanvändare och verktyg
// (Sonarr/Radarr, scenreleaser, svenska DVD-rippar, Plex/Jellyfin-namn, MakeMKV) skapar. Sökvägen är relativ
// biblioteksmappen; lib = bibliotekets namn (barnbibliotek ger förtur åt animerat/familj).
// Film:  [sökväg, titel, år, tmdb-id, { lib, dur (minuter) }]
// Serie: [sökväg, serie, år, säsong, avsnitt, tmdb-id, { lib, date }]
// titel/serie jämförs med söknyckeln (gemener, utan accenter och skiljetecken). tmdb-id null = ska inte matchas.

const mv = (lib) => (p, t, y, id, o = {}) => ({ kind: 'movie', lib, p, t, y, id, ...o });
const tv = (lib) => (p, s, y, se, ep, id, o = {}) => ({ kind: 'show', lib, p, s, y, se, ep, id, ...o });

const B = mv('Barnfilm'), F = mv('Filmer'), A = mv('Anime');
const BS = tv('Barnserier'), S = tv('Serier'), AS = tv('Anime'), J = tv('Julkalendrar');

